605	+ * as "the first element in DOM order": an inline svg that precedes the product name text and is not the
606	+ * flag of the chip. The look (surface, edge, size) is checked in the e2e file and the static specs.
607	+ */
608	+
609	+const TODAY = day(2026, 11, 21);
610	+const PRODUCT = 'Cotizador de seguro de auto';
611	+
612	+describe('US-04-AC-30 / US-04-BR-22 the header brand mark and product name', () => {
613	+  let app: AppTest;
614	+
615	+  beforeEach(() => {
616	+    configureAppTest({ today: TODAY });
617	+    vi.spyOn(console, 'warn').mockImplementation(() => undefined);
618	+  });
619	+  afterEach(() => {
620	+    vi.restoreAllMocks();
621	+    sessionStorage.clear();
622	+    TestBed.resetTestingModule();
623	+  });
624	+
625	+  const co = (): string => wizardEntryWithPlan('CO', CO_VALID_RAW, 'total');
626	+  const cl = (): string => wizardEntryWithPlan('CL', CL_SPEC_RAW, 'protegido');
627	+
628	+  const pages: [string, string | null, string | null][] = [
629	+    ['/', null, null],
630	+    ['/co/datos', 'Colombia', 'co'],
631	+    ['/cl/planes', 'Chile', 'cl'],
632	+  ];
633	+
634	+  async function show(address: string, entry: string | null): Promise<HTMLElement> {
635	+    if (entry) sessionStorage.setItem('quote-wizard', entry);
636	+    app = await createAppTest();
637	+    await app.open(address);
638	+    const header = wizardHeader(app.root);
639	+    expect(header, `a header at ${address}`).not.toBeNull();
640	+    return header as HTMLElement;
641	+  }
642	+
643	+  function productNameNode(header: HTMLElement): Text {
644	+    const walker = document.createTreeWalker(header, NodeFilter.SHOW_TEXT);
645	+    for (let node = walker.nextNode(); node; node = walker.nextNode()) {
646	+      if (normalise(node.textContent).includes(PRODUCT)) return node as Text;
647	+    }
648	+    throw new Error('The product name is not in the header');
649	+  }
650	+
651	+  const entryFor = (country: string | null): string | null => (country === 'Colombia' ? co() : country === 'Chile' ? cl() : null);
652	+
653	+  it.each(pages)('US-04-AC-30 at %s the first svg of the header is the brand mark: not inside a link, and before the product name', async (address, country) => {
654	+    const header = await show(address, entryFor(country));
655	+    const mark = header.querySelector('svg');
656	+    expect(mark, 'an inline svg in the header').not.toBeNull();
657	+    expect(mark?.closest('a'), 'the mark is not the chip flag').toBeNull();
658	+    const name = productNameNode(header);
659	+    expect((mark as SVGElement).compareDocumentPosition(name) & Node.DOCUMENT_POSITION_FOLLOWING, 'the product name follows the mark').toBeTruthy();
660	+  });
661	+
662	+  it.each(pages)('US-04-AC-30 at %s the mark has aria-hidden="true", no tabindex, no title, no desc and no text', async (address, country) => {
663	+    const header = await show(address, entryFor(country));
664	+    const mark = header.querySelector('svg') as SVGElement;
665	+    expect(mark.getAttribute('aria-hidden')).toBe('true');
666	+    expect(mark.hasAttribute('tabindex')).toBe(false);
667	+    expect(mark.querySelector('title, desc')).toBeNull();
668	+    expect(mark.textContent?.trim()).toBe('');
669	+    expect(mark.querySelector('text'), 'no <text> element').toBeNull();
670	+    expect(mark.querySelector('[tabindex]')).toBeNull();
671	+  });
672	+
673	+  it.each(pages)('US-04-AC-30 at %s the header has no img element and its text starts with the product name', async (address, country) => {
674	+    const header = await show(address, entryFor(country));
675	+    expect(header.querySelector('img')).toBeNull();
676	+    expect(normalise(header.textContent).startsWith(PRODUCT)).toBe(true);
677	+  });
678	+
679	+  it.each(pages)('US-04-AC-30 at %s the product name is not a heading and not a link', async (address, country) => {
680	+    const header = await show(address, entryFor(country));
681	+    const name = productNameNode(header);
682	+    expect(name.parentElement?.closest('h1, h2, h3, h4, h5, h6, a')).toBeNull();
683	+    expect(header.querySelector('h1, h2, h3, h4, h5, h6')).toBeNull();
684	+  });
685	+
686	+  it('US-04-AC-30 on the chooser the header has no link; on a wizard page it has one link, named "Cambiar país (actual: Colombia)", with the address "/" and the visible text "Colombia" (no "Cambiar" hint, US-04-Q-29)', async () => {
687	+    const chooser = await show('/', null);
688	+    expect(chooser.querySelectorAll('a, button, input, select, textarea, [tabindex]')).toHaveLength(0);
689	+    TestBed.resetTestingModule();
690	+    configureAppTest({ today: TODAY });
691	+    const wizard = await show('/co/datos', co());
692	+    const links = Array.from(wizard.querySelectorAll('a'));
693	+    expect(links).toHaveLength(1);
694	+    expect(nameOf(links[0])).toBe('Cambiar país (actual: Colombia)');
695	+    expect(links[0].getAttribute('href')).toBe('/');
696	+    expect(normalise(links[0].textContent)).toBe('Colombia');
697	+  });
698	+});
