1	import { readFileSync, statSync } from 'node:fs';
2	import { join } from 'node:path';
3	import { expect, test, type Locator, type Page } from '@playwright/test';
4	import { field } from './support/form';
5	import { TODAY, reachPlansInChile } from './support/plans';
6	import { acceptTerms, confirmedHeading, pagar, reachSummaryInChile, reachSummaryInColombia } from './support/summary';
7	import { VIEWPORTS, expectFocusIndicatorOnActive } from './support/design';
8	
9	/**
10	 * US-04 HC3 round 2 (spec v0.4, BR-22, BR-23) against the real stack with the seed: the header that
11	 * belongs to the page (AC-30: translucent token surface, gradient edge with the country accent, brand
12	 * mark, Archivo product name, chip link, height and clipping, reduced transparency, forced colors, no
13	 * motion) and the icons served by the web container (AC-31).
14	 *
15	 * The header is found by its role (`banner`; `includeHidden` because an open modal dialog makes it
16	 * aria-hidden). Colours, gradients and sizes are compared with the RESOLVED value of the token, read by
17	 * a probe element appended inside the header (so it inherits the country scope), never with a literal.
18	 */
19	
20	const PRODUCT = 'Cotizador de seguro de auto';
21	const CHIP_CO = 'Cambiar país (actual: Colombia)';
22	
23	const header = (page: Page): Locator => page.getByRole('banner', { includeHidden: true });
24	
25	type Accent = 'co' | 'cl' | null;
26	interface PageRow {
27	  name: string;
28	  accent: Accent;
29	  show: (page: Page) => Promise<void>;
30	}
31	
32	const CHOOSER: PageRow = {
33	  name: '"/" (country chooser)',
34	  accent: null,
35	  show: async (page) => {
36	    await page.goto('/');
37	    await expect(page.getByRole('heading', { level: 1, name: 'Elige tu país' })).toBeVisible();
38	  },
39	};
40	const CO_DATOS: PageRow = {
41	  name: '"/co/datos"',
42	  accent: 'co',
43	  show: async (page) => {
44	    await page.clock.setFixedTime(TODAY);
45	    await page.goto('/co/datos');
46	    await expect(field(page, 'Placa')).toBeVisible();
47	  },
48	};
49	const CL_PLANES: PageRow = { name: '"/cl/planes"', accent: 'cl', show: reachPlansInChile };
50	const CO_RESUMEN: PageRow = { name: '"/co/resumen"', accent: 'co', show: (page) => reachSummaryInColombia(page) };
51	const CL_CONFIRMATION: PageRow = {
52	  name: 'the payment confirmation in Chile',
53	  accent: 'cl',
54	  show: async (page) => {
55	    await reachSummaryInChile(page);
56	    await acceptTerms(page).check();
57	    await pagar(page).click();
58	    await expect(confirmedHeading(page)).toBeVisible();
59	  },
60	};
61	const ALL_PAGES = [CHOOSER, CO_DATOS, CL_PLANES, CO_RESUMEN, CL_CONFIRMATION];
62	
63	// ---------------------------------------------------------------------------------------------
64	// Readers (run in the page). A probe is a throwaway child of the header.
65	// ---------------------------------------------------------------------------------------------
66	
67	/** The computed value of `property` when it is set to `value` on a probe inside the header (a `var(--token)` is resolved in the header's scope). */
68	async function probe(page: Page, property: string, value: string): Promise<string> {
69	  return header(page).evaluate(
70	    (el, [prop, val]) => {
71	      const p = document.createElement('div');
72	      p.style.setProperty(prop, val);
73	      el.appendChild(p);
74	      const out = getComputedStyle(p).getPropertyValue(prop);
75	      p.remove();
76	      return out;
77	    },
78	    [property, value],
79	  );
80	}
81	
82	/** The resolved colour of the country accent of `key`, read on a probe with the accent attribute on the body. */
83	async function accentColour(page: Page, key: 'co' | 'cl'): Promise<string> {
84	  return page.evaluate((k) => {
85	    const p = document.createElement('div');
86	    p.setAttribute('data-country-accent', k);
87	    p.style.color = 'var(--color-country-accent)';
88	    document.body.appendChild(p);
89	    const out = getComputedStyle(p).color;
90	    p.remove();
91	    return out;
92	  }, key);
93	}
94	
95	const styleOf = (page: Page, property: string): Promise<string> => header(page).evaluate((el, prop) => getComputedStyle(el).getPropertyValue(prop), property);
96	
97	/** The alpha of a computed `rgb()`, `rgba()` or `color(srgb ... / a)` colour. */
98	function alphaOf(colour: string): number {
99	  const rgba = /^rgba\(([^)]*)\)$/.exec(colour.trim());
100	  if (rgba) return parseFloat(rgba[1].split(',')[3]);
101	  const mod = /\/\s*([\d.]+%?)\s*\)$/.exec(colour.trim());
102	  if (mod) return mod[1].endsWith('%') ? parseFloat(mod[1]) / 100 : parseFloat(mod[1]);
103	  return 1;
104	}
105	
106	interface Painter {
107	  where: string;
108	  image: string;
109	  borderImage: string;
110	  height: string;
111	  borderBottomWidth: string;
112	  borderBottomStyle: string;
113	  backgroundSize: string;
114	}
115	
116	/** Every element of the header, and its ::before / ::after, as a possible painter of the bottom edge. */
117	async function painters(page: Page): Promise<Painter[]> {
118	  return header(page).evaluate((root) => {
119	    const out: Painter[] = [];
120	    for (const el of [root, ...Array.from(root.querySelectorAll('*'))]) {
121	      for (const pseudo of [null, '::before', '::after'] as const) {
122	        const s = getComputedStyle(el, pseudo);
123	        if (pseudo && s.content === 'none') continue;
124	        out.push({
125	          where: `${el.tagName.toLowerCase()}${pseudo ?? ''}`,
126	          image: s.backgroundImage,
127	          borderImage: s.borderImageSource,
128	          height: pseudo ? s.height : `${el.getBoundingClientRect().height}px`,
129	          borderBottomWidth: s.borderBottomWidth,
130	          borderBottomStyle: s.borderBottomStyle,
131	          backgroundSize: s.backgroundSize,
132	        });
133	      }
134	    }
135	    return out;
136	  });
137	}
138	
139	const paintsGradient = (p: Painter, gradient: string): boolean => p.image.includes(gradient) || p.borderImage.includes(gradient);
140	const isOnePixel = (p: Painter): boolean => p.height === '1px' || (p.borderBottomWidth === '1px' && p.borderImage !== 'none') || /\b1px\b/.test(p.backgroundSize);
141	
142	/** Put a tall test-only spacer in the block that contains the sticky header, so there is something to scroll. */
143	async function makePageTall(page: Page): Promise<void> {
144	  await header(page).evaluate((el) => {
145	    let parent = el.parentElement as HTMLElement;
146	    while (getComputedStyle(parent).display === 'contents' && parent.parentElement) parent = parent.parentElement;
147	    if (parent.querySelector(':scope > [data-test-spacer]')) return;
148	    const spacer = document.createElement('div');
149	    spacer.setAttribute('data-test-spacer', ''); // test-only layout aid: re-added when the page re-renders its container
150	    spacer.setAttribute('aria-hidden', 'true');
151	    spacer.style.height = '3000px';
152	    parent.appendChild(spacer);
153	  });
154	}
155	
156	interface Boxes {
157	  header: DOMRect;
158	  mark: DOMRect;
159	  name: DOMRect;
160	  chip: DOMRect | null;
161	  nameScrollWidth: number;
162	  nameClientWidth: number;
163	  nameEllipsis: string;
164	  nameLines: number;
165	}
166	
167	/** The first svg of the header that is not inside a link, the element holding the product name, and the chip. */
168	async function boxesOf(page: Page): Promise<Boxes> {
169	  return header(page).evaluate((root, product) => {
170	    const mark = Array.from(root.querySelectorAll('svg')).find((s) => !s.closest('a'));
171	    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
172	    let nameEl: HTMLElement | null = null;
173	    for (let n = walker.nextNode(); n && !nameEl; n = walker.nextNode()) {
174	      if ((n.textContent ?? '').replace(/\s+/g, ' ').includes(product)) nameEl = n.parentElement;
175	    }
176	    const chip = root.querySelector('a');
177	    if (!mark || !nameEl) throw new Error('The header has no brand mark or no product name');
178	    const range = document.createRange();
179	    range.selectNodeContents(nameEl);
180	    const tops = new Set(Array.from(range.getClientRects()).map((r) => Math.round(r.top)));
181	    return {
182	      header: root.getBoundingClientRect(),
183	      mark: mark.getBoundingClientRect(),
184	      name: nameEl.getBoundingClientRect(),
185	      chip: chip ? chip.getBoundingClientRect() : null,
186	      nameScrollWidth: nameEl.scrollWidth,
187	      nameClientWidth: nameEl.clientWidth,
188	      nameEllipsis: getComputedStyle(nameEl).textOverflow,
189	      nameLines: tops.size,
190	    };
191	  }, PRODUCT);
192	}
193	
194	async function emulateReducedTransparency(page: Page): Promise<void> {
195	  const session = await page.context().newCDPSession(page);
196	  await session.send('Emulation.setEmulatedMedia', { features: [{ name: 'prefers-reduced-transparency', value: 'reduce' }] });
197	}
198	
199	// ---------------------------------------------------------------------------------------------
200	test.describe('US-04-AC-30 translucent surface with a gradient edge (1280 x 800)', () => {
201	  for (const row of ALL_PAGES) {
202	    test(`US-04-AC-30 ${row.name}: the header background is --component-header-bg (translucent, not --color-surface-raised) and its backdrop-filter is --component-header-backdrop`, async ({ page }) => {
203	      await page.setViewportSize(VIEWPORTS.desktop);
204	      await row.show(page);
205	      const background = await styleOf(page, 'background-color');
206	      expect(background, 'not the old raised surface').not.toBe(await probe(page, 'background-color', 'var(--color-surface-raised)'));
207	      expect(background, 'the component token').toBe(await probe(page, 'background-color', 'var(--component-header-bg)'));
208	      const alpha = alphaOf(background);
209	      expect(alpha, `alpha of ${background}`).toBeGreaterThan(0);
210	      expect(alpha, `alpha of ${background}`).toBeLessThan(1);
211	      const backdrop = await styleOf(page, 'backdrop-filter');
212	      expect(backdrop).not.toBe('none');
213	      expect(backdrop).toBe(await probe(page, 'backdrop-filter', 'var(--component-header-backdrop)'));
214	    });
215	
216	    test(`US-04-AC-30 ${row.name}: the bottom edge is 1 CSS px and painted with --gradient-header-edge, and no grey hairline remains`, async ({ page }) => {
217	      await page.setViewportSize(VIEWPORTS.desktop);
218	      await row.show(page);
219	      const edge = await probe(page, 'background-image', 'var(--gradient-header-edge)');
220	      expect(edge, 'the token resolves to a gradient').toMatch(/linear-gradient/);
221	      const all = await painters(page);
222	      const painter = all.filter((p) => paintsGradient(p, edge));
223	      expect(painter.map((p) => p.where), 'an element, pseudo-element or border image that paints the edge gradient').not.toEqual([]);
224	      expect(painter.some(isOnePixel), `the edge is 1px tall: ${JSON.stringify(painter)}`).toBe(true);
225	      // the header's own border-bottom is not a plain line: it is zero, none, or the gradient border image
226	      const own = all[0];
227	      const plain = own.borderBottomStyle !== 'none' && parseFloat(own.borderBottomWidth) > 0 && own.borderImage === 'none';
228	      expect(plain, `the header keeps a plain border-bottom: ${own.borderBottomWidth} ${own.borderBottomStyle}`).toBe(false);
229	    });
230	
231	    test(`US-04-AC-30 ${row.name}: the header stays at the top of the viewport after scrolling down 400 CSS px`, async ({ page }) => {
232	      await page.setViewportSize(VIEWPORTS.desktop);
233	      await row.show(page);
234	      await expect
235	        .poll(async () => {
236	          await makePageTall(page);
237	          await page.evaluate(() => window.scrollTo(0, 400));
238	          return page.evaluate(() => window.scrollY);
239	        })
240	        .toBeGreaterThanOrEqual(399);
241	      const top = await header(page).evaluate((el) => el.getBoundingClientRect().top);
242	      expect(top).toBeGreaterThanOrEqual(-0.5);
243	      expect(top).toBeLessThanOrEqual(0.5);
244	    });
245	  }
246	});
247	
248	test.describe('US-04-AC-30 the edge carries the country accent only as decoration', () => {
249	  for (const row of [CO_DATOS, CL_PLANES, CHOOSER]) {
250	    test(`US-04-AC-30 ${row.name}: the stops of the edge ${row.accent ? `include the ${row.accent === 'co' ? 'Colombia' : 'Chile'} accent` : 'hold no country accent (brand violets only)'}, and no header text has an accent colour`, async ({ page }) => {
251	      await page.setViewportSize(VIEWPORTS.desktop);
252	      await row.show(page);
253	      const co = await accentColour(page, 'co');
254	      const cl = await accentColour(page, 'cl');
255	      const edge = (await painters(page)).filter((p) => p.image.includes('linear-gradient') || p.borderImage.includes('linear-gradient')).map((p) => `${p.image} ${p.borderImage}`).join(' ');
256	      expect(edge, 'a painted gradient edge').not.toBe('');
257	      if (row.accent) {
258	        expect(edge).toContain(row.accent === 'co' ? co : cl);
259	        expect(edge).not.toContain(row.accent === 'co' ? cl : co);
260	      } else {
261	        expect(edge).not.toContain(co);
262	        expect(edge).not.toContain(cl);
263	      }
264	      const textColours = await header(page).evaluate((root) => {
265	        const out: string[] = [];
266	        for (const el of Array.from(root.querySelectorAll('*'))) {
267	          const own = Array.from(el.childNodes).some((n) => n.nodeType === Node.TEXT_NODE && (n.textContent ?? '').trim() !== '');
268	          if (own) out.push(getComputedStyle(el).color);
269	        }
270	        return out;
271	      });
272	      expect(textColours.length, 'text elements in the header').toBeGreaterThan(0);
273	      expect(textColours).not.toContain(co);
274	      expect(textColours).not.toContain(cl);
275	    });
276	  }
277	});
278	
279	test.describe('US-04-AC-30 brand mark and product name', () => {
280	  for (const row of [CHOOSER, CO_DATOS]) {
281	    test(`US-04-AC-30 ${row.name}: the first content of the header is the brand mark (svg, aria-hidden, no tabindex, title or desc, no text, size --size-brand-mark), followed by the product name`, async ({ page }) => {
282	      await page.setViewportSize(VIEWPORTS.desktop);
283	      await row.show(page);
284	      const first = await header(page).evaluate((root, product) => {
285	        // content elements in DOM order: svg, img, links, buttons, and elements with their own text
286	        const content = Array.from(root.querySelectorAll('*')).filter((el) => {
287	          if (el.closest('svg') && el.tagName.toLowerCase() !== 'svg') return false;
288	          const r = el.getBoundingClientRect();
289	          if (r.width === 0 || r.height === 0) return false;
290	          const own = Array.from(el.childNodes).some((n) => n.nodeType === Node.TEXT_NODE && (n.textContent ?? '').trim() !== '');
291	          return ['svg', 'img', 'a', 'button'].includes(el.tagName.toLowerCase()) || own;
292	        });
293	        const mark = content[0];
294	        const nameIndex = content.findIndex((el) => (el.textContent ?? '').replace(/\s+/g, ' ').includes(product) && el.tagName.toLowerCase() !== 'svg');
295	        return {
296	          tag: mark?.tagName.toLowerCase(),
297	          inLink: !!mark?.closest('a'),
298	          ariaHidden: mark?.getAttribute('aria-hidden'),
299	          hasTabindex: mark?.hasAttribute('tabindex'),
300	          titleOrDesc: mark?.querySelector('title, desc') !== null,
301	          text: (mark?.textContent ?? '').trim(),
302	          width: mark?.getBoundingClientRect().width,
303	          height: mark?.getBoundingClientRect().height,
304	          nameIndex,
305	          imgCount: root.querySelectorAll('img').length,
306	          text0: (root.textContent ?? '').replace(/\s+/g, ' ').trim(),
307	        };
308	      }, PRODUCT);
309	      expect(first.tag, 'the first element with a rendered box and content').toBe('svg');
310	      expect(first.inLink).toBe(false);
311	      expect(first.nameIndex, 'the product name follows the mark').toBeGreaterThan(0);
312	      expect(first.ariaHidden).toBe('true');
313	      expect(first.hasTabindex).toBe(false);
314	      expect(first.titleOrDesc).toBe(false);
315	      expect(first.text).toBe('');
316	      expect(first.imgCount).toBe(0);
317	      expect(first.text0.startsWith(PRODUCT)).toBe(true);
318	      const size = await probe(page, 'width', 'var(--size-brand-mark)');
319	      expect(parseFloat(size), `--size-brand-mark resolves to ${size}`).toBeGreaterThan(0);
320	      expect(Math.abs((first.width as number) - parseFloat(size))).toBeLessThanOrEqual(1);
321	      expect(Math.abs((first.height as number) - parseFloat(size))).toBeLessThanOrEqual(1);
322	      expect(Math.abs((first.width as number) - 32), 'also 32 px at the default root size').toBeLessThanOrEqual(1);
323	    });
324	
325	    test(`US-04-AC-30 ${row.name}: the product name is not a heading and not a link, and its first font family is Archivo`, async ({ page }) => {
326	      await page.setViewportSize(VIEWPORTS.desktop);
327	      await row.show(page);
328	      await expect(header(page).getByRole('heading')).toHaveCount(0);
